    window.setTimeout(fitHeight, 80);
    window.setTimeout(fitHeight, 260);
  }

  function setMode(root, mode) {
    mode = mode === 'raw' ? 'raw' : 'render';
    var btns = root.querySelectorAll('.tc-mode');
    for (var i = 0; i < btns.length; i++) {
      var m = btns[i].getAttribute('data-tc-mode');
      if (m === mode) { btns[i].classList.add('is-on'); } else { btns[i].classList.remove('is-on'); }
    }
    var r = root.querySelector('.tc-render');
    var w = root.querySelector('.tc-raw');
    if (r) { r.hidden = mode !== 'render'; }
    if (w) { w.hidden = mode !== 'raw'; }
