    window.setTimeout(fitHeight, 80);
  }

  function boot(root) {
    try { adoptTheme(root); } catch (e) { }

    var holder = root.querySelector('.tc-md');
    var raw = holder ? trim(holder.textContent) : '';

    var meta = root.querySelector('.tc-hl-n');
    if (meta) { meta.textContent = raw.replace(/\s/g, '').length + ' 字'; }

    var render = root.querySelector('.tc-render');
    if (render) {
      if (!raw || raw === PLACEHOLDER) {
        render.innerHTML = '<p class="tc-empty">（未捕获到思维链内容：请检查正则捕获组是否正确传入）</p>';
      } else {
        try { render.innerHTML = md(raw); } catch (e) { render.textContent = raw; }
      }
    }
    var rawEl = root.querySelector('.tc-raw');
